package com.yuegang.zhihui.knowledge.application;import com.yuegang.zhihui.common.mq.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.autoconfigure.condition.*;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.*;import org.springframework.scheduling.annotation.*;
@Configuration(proxyBeanMethods=false)@ConditionalOnProperty(name="ygh.mq.enabled",havingValue="true")class KnowledgeOutboxConfiguration{@Bean(destroyMethod="close")DomainEventPublisher knowledgeEventPublisher(@Value("${ygh.mq.nameserver}")String n,@Value("${ygh.mq.topic:YGH_DOMAIN_EVENTS}")String t){return new RocketMqDomainEventPublisher("ygh-knowledge-producer",n,t);}@Bean KnowledgeOutboxJob knowledgeOutboxJob(JdbcTemplate j,DomainEventPublisher p){return new KnowledgeOutboxJob(new JdbcOutboxDispatcher(j,p,"knowledge_outbox"));}static final class KnowledgeOutboxJob{private final JdbcOutboxDispatcher d;KnowledgeOutboxJob(JdbcOutboxDispatcher x){d=x;}@Scheduled(fixedDelayString="${ygh.mq.dispatch-delay:1000}")public void dispatch(){d.dispatch();}}}
